insert into contract_events (id, contract_id, tender_id, type, event_date, summary, user_name, occurred_at)
select gen_random_uuid(), c.id, c.tender_id, 'SIGNED', c.signed_at, 'Contrato registrado pelo seed', 'Seed de desenvolvimento', now()
from contracts c
where c.created_by = 'seed'
  and not exists (select 1 from contract_events e where e.contract_id = c.id);
